      } else {
        cur.fadeOut(now, Math.max(0.03, fade));
        p.fadeIn(t0, fade > 0 ? fade * 0.5 : 0.01);
      }
    } else p.fadeIn(t0, 0.01);
    this.current = p;
    this._tick();
  }

  _onFileFailed(player, error) {
    if (this._preloadedFile?.player === player) {
      this._fileFailures.add(player.id);
      this._dropPreload();
      return; // A START-gesture failure can be tried again when GO is requested.
    }
    if (this.current !== player) return; // Ignore failures from already retired players.
    player.dispose();
    this.players = this.players.filter((p) => p !== player);
    this.current = null;
    this._retryFile(player.id, error);
  }

  setIntensity(x) {
    this.intensity = Math.min(1, Math.max(0, +x || 0));
    if (!this.ctx) return;
    const now = this.now();
    for (const p of this.players) p.setIntensity(this.intensity, now);
  }

  stop(fade = 1) { this.play(null, { fade }); }

  dispose() {
    this._musicDest = null;
    this._preparedMusicImpulse = null;
    this.dlyIn = this.revIn = this.dA = this.dB = null;
    this._cancelFileRetry();
    this._desiredTrack = null;
    this._dropPreload();
    this._timerPaused = true;
    for (const p of this.players) p.dispose();
    this.players.length = 0; this.current = null;
    if (this.worker) { this.worker.postMessage(0); this.worker.terminate(); this.worker = null; }
    if (this.timer) { clearInterval(this.timer); this.timer = null; }
    for (const n of this._nodes || []) { try { n.disconnect(); } catch (e) { /* */ } }
    this.ctx = null;
  }
}

export const TRACKS = Object.fromEntries(Object.entries(SONGS).map(([id, s]) => [id, {
  name: s.name, bpm: s.bpm, key: s.key,
  structure: s.order.map((k) => `${k}(${s.sections[k].bars})`).join(' → ') + `, loops from ${s.order[s.loopFrom ?? 0]}`,
}]));

installMusicIdle(MusicEngine);
export const music = new MusicEngine();

installMusicPlatform(MusicEngine);
